-- What the archive job needs in order to stop losing data (hardening plan §28).
--
--   - archived_receipts had no payment_method, so the archive dropped how each
--     payment was made, on a record kept five years for tax and audit;
--   - archived_trainee_subscriptions had no expired_at;
--   - manual income had no archive table at all, so after five years its ledger
--     rows were archived and its rows were not, and the two disagreed.
--
-- (All generated by Prisma.)

-- AlterTable
ALTER TABLE "archived_trainee_subscriptions" ADD COLUMN     "expired_at" TIMESTAMPTZ;

-- AlterTable
ALTER TABLE "archived_receipts" ADD COLUMN     "payment_method" "PaymentMethod";

-- CreateTable
CREATE TABLE "archived_manual_incomes" (
    "id" UUID NOT NULL,
    "branch_id" UUID NOT NULL,
    "category" VARCHAR(100) NOT NULL,
    "amount" DECIMAL(10,2) NOT NULL,
    "description" TEXT,
    "date" DATE NOT NULL,
    "created_by" UUID NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL,
    "updated_at" TIMESTAMPTZ NOT NULL,
    "archived_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "archived_manual_incomes_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "archived_manual_incomes_branch_id_date_idx" ON "archived_manual_incomes"("branch_id", "date");
